INSERT INTO "Бирюлёвский дендропарк: проект 1965"."Сущ. грунтовые аллеи и дороги" ("№ п/п","Аллеи и дороги","Протяжённость в м","Ширина в м","Площадь м²","Сост. насажд. в аллеях и оп. дорог","Wikidata Q")
	VALUES (1,'Лиственница сибирская',360,5,1800,'Лиственниц 153 штуки посажено в 1943-1946 годах. Состояние хорошее, деревья крупные высотой 6,0-7,0 м, единичные до 8,0 м, несколько мелких высотой 3,5-4,0 м. Диаметры от 10,0 до 20,0 см, единичные до 22,0 см. Размеры крон 3,0 м × 4,0 м × 5,0 м. Начинаются кроны на высоте 0,5-0,8 м от земли.
В северной части аллеи деревья мельче. Цветёт и плодоносит. Расстояние между стволами не одинаковые от 3,0 м — 4,0 м до 5,0 - 6,0 м. (Часть растений выкопана). Имеющиеся разрывы раскрывают вид на прилегающие площадки и группы.','Q138674264');
INSERT INTO "Бирюлёвский дендропарк: проект 1965"."Сущ. грунтовые аллеи и дороги" ("№ п/п","Аллеи и дороги","Протяжённость в м","Ширина в м","Площадь м²","Сост. насажд. в аллеях и оп. дорог","Wikidata Q")
	VALUES (2,'Липа мелколистная',210,5,1050,'Лип - 78 штук, посажены в 1944-45 годах, саженцами высотой 1,5 м. Состояние хорошее, обильно цветёт и плодоносит. Высота растений 5,0 - 6,0 м, диаметр 8,0 - 14,0 см. Кроны начинаются на высоте 0,6-1,0 м от земли, размер крон 3,0 м × 3,0 м, 3,0 × 4,0 м. Расстояния между стволами 5,0 м, местами 8,0-10 м.','Q138674272');
INSERT INTO "Бирюлёвский дендропарк: проект 1965"."Сущ. грунтовые аллеи и дороги" ("№ п/п","Аллеи и дороги","Протяжённость в м","Ширина в м","Площадь м²","Сост. насажд. в аллеях и оп. дорог","Wikidata Q")
	VALUES (3,'Ель обыкновенная',530,5,2650,'Северный отрезок аллеи - (до «Большой поляны») посадка 1944-45 годов саженцами 5-летними, высотой 1,0 м. Всего 197 штук. Состояние хорошее. Высота от 4,0 до 5,5 м, диаметр 6,0-12,0 см. 9 растений угнетённые, со сломанными вершинами, их нужно вырубить. Кроны начинаются на высоте 0,3 м от земли. В ряду кроны сомкнулись полностью, прирост последних лет по 30-40 см. Расстояние между стволами 2,0 м. Цветение и плодоношение редкое. Южный отрезок - посадка 1939 г., всего 222 штук(и). Высота деревьев до 8,0-8,5 м с диаметрами до 14,0 см. Цветут и плодоносят. Из 222 штук 10 угнетённых.','Q138674270');
INSERT INTO "Бирюлёвский дендропарк: проект 1965"."Сущ. грунтовые аллеи и дороги" ("№ п/п","Аллеи и дороги","Протяжённость в м","Ширина в м","Площадь м²","Сост. насажд. в аллеях и оп. дорог","Wikidata Q")
	VALUES (4,'Белая акация',430,3,1290,'Состояние хорошее, белая акация имеет форму кустовидную - у каждого растения по 2-4 стволика, но кроны начинаются на высоте 1,0-1,5 м. Цветёт и плодоносит обильно. Обмерзает, но незначительно. Высота растений от 2,5 до 5,0 м. Расстояние между стволами 3,0 м. Всего в аллее 149 штук. Сомкнулись кроны полностью и в ряду и над аллеей.','Q138674280');
INSERT INTO "Бирюлёвский дендропарк: проект 1965"."Сущ. грунтовые аллеи и дороги" ("№ п/п","Аллеи и дороги","Протяжённость в м","Ширина в м","Площадь м²","Сост. насажд. в аллеях и оп. дорог","Wikidata Q")
	VALUES (5,'Ясень',180,3,540,'В аллее 121 дерево. Состояние растений на южном отрезке хорошее, деревья крупные высотой до 5,0 м с хорошо развитой кроной 2,5 × 3 м. На северном отрезке состояние плохое, высота деревьев до 3,5-4,0 м, кроны маленькие 1,5×1,5 м, чахлые. В 1962 г. цветения не было, в 1964 г. цветение и плодоношение вредней силы. Вдоль аллеи полоса из дрока красильного шириной до 2,0 м, обильно цветёт и плодоносит, дала поросль.','Q138674276');
INSERT INTO "Бирюлёвский дендропарк: проект 1965"."Сущ. грунтовые аллеи и дороги" ("№ п/п","Аллеи и дороги","Протяжённость в м","Ширина в м","Площадь м²","Сост. насажд. в аллеях и оп. дорог","Wikidata Q")
	VALUES (6,'Берёза',110,5,550,'На этом отрезке аллеи 86 штук берёз, посадка произведена в 1943-44 гг. Крупные красивые деревья высотой до 15-16 м с диаметром от 10 до 20 см. Кроны в ряду сомкнулись полностью и над аллеей образовали шатер. Расстояние между стволами - 2,0 м.','Q138674271');
INSERT INTO "Бирюлёвский дендропарк: проект 1965"."Сущ. грунтовые аллеи и дороги" ("№ п/п","Аллеи и дороги","Протяжённость в м","Ширина в м","Площадь м²","Сост. насажд. в аллеях и оп. дорог","Wikidata Q")
	VALUES (7,'Рябина',120,3,360,'Состояние хорошее, крупные красивые деревья высотой до 5,0 м. с диаметром до 5,0-6,0 см. (7 растений посажено в 1961 г., их высота 2,5 м). Обильно цветёт и плодоносит. Вдоль аллеи полоса дрока красильного шириной до 2,0 м. - размножение порослью, цветёт обильно.','Q138674277');
INSERT INTO "Бирюлёвский дендропарк: проект 1965"."Сущ. грунтовые аллеи и дороги" ("№ п/п","Аллеи и дороги","Протяжённость в м","Ширина в м","Площадь м²","Сост. насажд. в аллеях и оп. дорог","Wikidata Q")
	VALUES (8,'Туя западная',130,2,260,'211 туй по аллее, из них 4 растения угнетены дубом растущим на аллее, остальные растения красивой пирамидальной формы и хорошего состояния. Высота их 2,0-2,5 м. Посажена была на расстоянии 0,6 м, из аллеи выкопали до 50% растений, теперь расстояния 1,2-1,5 м.','Q138674285');
INSERT INTO "Бирюлёвский дендропарк: проект 1965"."Сущ. грунтовые аллеи и дороги" ("№ п/п","Аллеи и дороги","Протяжённость в м","Ширина в м","Площадь м²","Сост. насажд. в аллеях и оп. дорог","Wikidata Q")
	VALUES (9,'Дорога между кварталами 1, 14, 18, 17 и 12, 25, 27',500,5,2500,'Широкая дорога проложена в естественном берёзовом массиве, живописная.','Q138679481');
